inputs = ['jcjycb', 'jfha', 'dygchz', 'hfde', 'ikcuyu']
outputs = ['jcjycb', 'jfbgva', 'dygcij', 'bgvfde', 'idzduyu']

print("Character-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n'{inp}' → '{outp}'")
    # Check positions where characters differ
    min_len = min(len(inp), len(outp))
    for pos in range(max(len(inp), len(outp))):
        in_char = inp[pos] if pos < len(inp) else None
        out_char = outp[pos] if pos < len(outp) else None
        if in_char != out_char:
            print(f"  Position {pos}: '{in_char}' → '{out_char}'")

print("\nLooking for patterns where characters are simply substituted:")
# Look for direct character substitutions that appear consistently
substitutions = {}
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    min_len = min(len(inp), len(outp))
    for pos in range(min_len):
        if inp[pos] != outp[pos]:
            if inp[pos] not in substitutions:
                substitutions[inp[pos]] = outp[pos]
            elif substitutions[inp[pos]] != outp[pos]:
                print(f"Conflict: '{inp[pos]}' maps to both '{substitutions[inp[pos]]}' and '{outp[pos]}'")

print(f"\nDirect substitutions found: {substitutions}")

